export function translateSettingsPageCopy(english, language) {
  const localized = labels[language];
  if (english === 'MusPlay') return english;
  if (!localized) return english;
  if (localized[english]) return localized[english];

  // Dynamic library/cache status messages for the additional app languages.
  const dynamic = extraDynamicMessages[language];
  let dynamicMatch = english.match(/^Added (\d+) tracks\. Found (\d+) files\.$/);
  if (dynamicMatch && dynamic) return dynamic.added(dynamicMatch[1], dynamicMatch[2]);
  dynamicMatch = english.match(/^No new tracks\. Found (\d+) files\.$/);
  if (dynamicMatch && dynamic) return dynamic.noNew(dynamicMatch[1]);
  dynamicMatch = english.match(/^ Skipped large files: (\d+)\.$/);
  if (dynamicMatch && dynamic) return dynamic.skipped(dynamicMatch[1]);
  dynamicMatch = english.match(/^Removed (\d+) cached lyrics entries\.$/);
  if (dynamicMatch && dynamic) return dynamic.removed(dynamicMatch[1]);

  let match = english.match(/^Added (\d+) tracks\. Found (\d+) files\.$/);
  if (match) {
    const [, tracks, files] = match;
    const messages = {
      es: `Se añadieron ${tracks} canciones. Se encontraron ${files} archivos.`,
      fr: `${tracks} titres ajoutés. ${files} fichiers trouvés.`,
      de: `${tracks} Titel hinzugefügt. ${files} Dateien gefunden.`,
      pt: `${tracks} faixas adicionadas. ${files} ficheiros encontrados.`,
      it: `Aggiunti ${tracks} brani. Trovati ${files} file.`,
      pl: `Dodano ${tracks} utworów. Znaleziono ${files} plików.`,
      uk: `Додано треків: ${tracks}. Знайдено файлів: ${files}.`,
      tr: `${tracks} parça eklendi. ${files} dosya bulundu.`,
      nl: `${tracks} nummers toegevoegd. ${files} bestanden gevonden.`,
      kk: `Қосылған тректер: ${tracks}. Табылған файлдар: ${files}.`,
    };
    return messages[language] || english;
  }
  match = english.match(/^No new tracks\. Found (\d+) files\.$/);
  if (match) {
    const files = match[1];
    const messages = {
      es: `No hay canciones nuevas. Se encontraron ${files} archivos.`,
      fr: `Aucun nouveau titre. ${files} fichiers trouvés.`,
      de: `Keine neuen Titel. ${files} Dateien gefunden.`,
      pt: `Não há faixas novas. ${files} ficheiros encontrados.`,
      it: `Nessun nuovo brano. Trovati ${files} file.`,
      pl: `Brak nowych utworów. Znaleziono ${files} plików.`,
      uk: `Нових треків немає. Знайдено файлів: ${files}.`,
      tr: `Yeni parça yok. ${files} dosya bulundu.`,
      nl: `Geen nieuwe nummers. ${files} bestanden gevonden.`,
      kk: `Жаңа трек жоқ. Табылған файлдар: ${files}.`,
    };
    return messages[language] || english;
  }
  match = english.match(/^ Skipped large files: (\d+)\.$/);
  if (match) {
    const count = match[1];
    const messages = {
      es: ` Se omitieron archivos grandes: ${count}.`,
      fr: ` Fichiers volumineux ignorés : ${count}.`,
      de: ` Große Dateien übersprungen: ${count}.`,
      pt: ` Ficheiros grandes ignorados: ${count}.`,
      it: ` File di grandi dimensioni ignorati: ${count}.`,
      pl: ` Pominięto duże pliki: ${count}.`,
      uk: ` Пропущено великих файлів: ${count}.`,
      tr: ` Büyük dosyalar atlandı: ${count}.`,
      nl: ` Grote bestanden overgeslagen: ${count}.`,
      kk: ` Өлшемі үлкен файлдар өткізіліп жіберілді: ${count}.`,
    };
    return messages[language] || english;
  }
  match = english.match(/^Removed (\d+) cached lyrics entries\.$/);
  if (match) {
    const count = match[1];
    const messages = {
      es: `Entradas de letras eliminadas de la caché: ${count}.`,
      fr: `Entrées de paroles supprimées du cache : ${count}.`,
      de: `Einträge aus dem Songtext-Cache entfernt: ${count}.`,
      pt: `Entradas de letras removidas da cache: ${count}.`,
      it: `Voci della cache dei testi rimosse: ${count}.`,
      pl: `Usunięto wpisów z pamięci tekstów: ${count}.`,
      uk: `Видалено записів кешу текстів: ${count}.`,
      tr: `Önbellekten kaldırılan şarkı sözü kaydı: ${count}.`,
      nl: `Songtekstcache-items verwijderd: ${count}.`,
      kk: `Кэштен жойылған ән мәтіндері жазбалары: ${count}.`,
    };
    return messages[language] || english;
  }
  return english;
}

const extended = {
  'Scanning music folders…': ['Analizando las carpetas de música…','Analyse des dossiers musicaux…','Musikordner werden durchsucht…','A analisar as pastas de música…','Scansione delle cartelle musicali…','Skanowanie folderów muzycznych…','Сканую музичні папки…','Müzik klasörleri taranıyor…','Muziekmappen scannen…'],
  'No audio files found.': ['No se encontraron archivos de audio.','Aucun fichier audio trouvé.','Keine Audiodateien gefunden.','Não foram encontrados ficheiros de áudio.','Nessun file audio trovato.','Nie znaleziono plików audio.','Аудіофайли не знайдено.','Ses dosyası bulunamadı.','Geen audiobestanden gevonden.'],
  ' Scan limit reached.': [' Se alcanzó el límite de análisis.',' Limite d’analyse atteint.',' Scanlimit erreicht.',' Limite de análise atingido.',' Limite di scansione raggiunto.',' Osiągnięto limit skanowania.',' Досягнуто ліміту сканування.',' Tarama sınırına ulaşıldı.',' Scanlimiet bereikt.'],
  'Could not scan the selected folders.': ['No se pudieron analizar las carpetas seleccionadas.','Impossible d’analyser les dossiers sélectionnés.','Die ausgewählten Ordner konnten nicht durchsucht werden.','Não foi possível analisar as pastas selecionadas.','Impossibile analizzare le cartelle selezionate.','Nie udało się przeskanować wybranych folderów.','Не вдалося просканувати вибрані папки.','Seçilen klasörler taranamadı.','De geselecteerde mappen konden niet worden gescand.'],
  'Could not add the folder.': ['No se pudo añadir la carpeta.','Impossible d’ajouter le dossier.','Der Ordner konnte nicht hinzugefügt werden.','Não foi possível adicionar a pasta.','Impossibile aggiungere la cartella.','Nie udało się dodać folderu.','Не вдалося додати папку.','Klasör eklenemedi.','De map kon niet worden toegevoegd.'],
  'Could not save the tray preference.': ['No se pudo guardar la preferencia de la bandeja.','Impossible d’enregistrer le réglage de la zone de notification.','Die Einstellung für den Infobereich konnte nicht gespeichert werden.','Não foi possível guardar a preferência da área de notificação.','Impossibile salvare la preferenza dell’area di notifica.','Nie udało się zapisać ustawienia zasobnika systemowego.','Не вдалося зберегти налаштування системного трея.','Sistem tepsisi tercihi kaydedilemedi.','De systeemvakvoorkeur kon niet worden opgeslagen.'],
  'Could not change the Windows startup setting.': ['No se pudo cambiar la opción de inicio de Windows.','Impossible de modifier le paramètre de démarrage de Windows.','Die Windows-Starteinstellung konnte nicht geändert werden.','Não foi possível alterar a opção de arranque do Windows.','Impossibile modificare l’impostazione di avvio di Windows.','Nie udało się zmienić ustawienia uruchamiania Windows.','Не вдалося змінити параметр автозапуску Windows.','Windows başlangıç ayarı değiştirilemedi.','De Windows-opstartinstelling kon niet worden gewijzigd.'],
  'Settings backup exported.': ['Copia de seguridad exportada.','Sauvegarde des paramètres exportée.','Einstellungssicherung exportiert.','Cópia de segurança das definições exportada.','Backup delle impostazioni esportato.','Wyeksportowano kopię zapasową ustawień.','Резервну копію налаштувань експортовано.','Ayar yedeği dışa aktarıldı.','Back-up van instellingen geëxporteerd.'],
  'Settings restored. Some system preferences take effect after restart.': ['Configuración restaurada. Algunas opciones del sistema se aplicarán tras reiniciar.','Paramètres restaurés. Certains réglages système prendront effet après le redémarrage.','Einstellungen wiederhergestellt. Einige Systemeinstellungen werden nach einem Neustart übernommen.','Definições restauradas. Algumas opções do sistema só serão aplicadas após reiniciar.','Impostazioni ripristinate. Alcune preferenze di sistema saranno applicate dopo il riavvio.','Przywrócono ustawienia. Niektóre opcje systemowe zostaną zastosowane po ponownym uruchomieniu.','Налаштування відновлено. Деякі системні параметри набудуть чинності після перезапуску.','Ayarlar geri yüklendi. Bazı sistem tercihleri yeniden başlatma sonrasında uygulanır.','Instellingen hersteld. Sommige systeemvoorkeuren worden na opnieuw opstarten toegepast.'],
  'This is not a valid MusPlay settings backup.': ['Este archivo no es una copia de seguridad válida de MusPlay.','Ce fichier n’est pas une sauvegarde MusPlay valide.','Dies ist keine gültige MusPlay-Einstellungssicherung.','Este ficheiro não é uma cópia de segurança válida do MusPlay.','Questo non è un backup valido delle impostazioni di MusPlay.','To nie jest prawidłowa kopia zapasowa ustawień MusPlay.','Це не є коректною резервною копією налаштувань MusPlay.','Bu geçerli bir MusPlay ayar yedeği değil.','Dit is geen geldige back-up van MusPlay-instellingen.'],
  'Reset MusPlay settings to defaults? Your music library and playlists will not be deleted.': ['¿Restablecer la configuración de MusPlay? La biblioteca y las listas no se eliminarán.','Rétablir les paramètres par défaut de MusPlay ? Votre médiathèque et vos playlists ne seront pas supprimées.','MusPlay auf Standardeinstellungen zurücksetzen? Mediathek und Playlists bleiben erhalten.','Repor as predefinições do MusPlay? A biblioteca e as listas de reprodução não serão eliminadas.','Ripristinare le impostazioni predefinite di MusPlay? La libreria e le playlist non verranno eliminate.','Przywrócić domyślne ustawienia MusPlay? Biblioteka muzyki i playlisty nie zostaną usunięte.','Скинути налаштування MusPlay до стандартних? Музичну медіатеку та плейлисти не буде видалено.','MusPlay varsayılan ayarlarına sıfırlansın mı? Müzik kitaplığın ve çalma listelerin silinmez.','MusPlay-instellingen terugzetten naar de standaardwaarden? Je muziekbibliotheek en afspeellijsten blijven behouden.'],
  'Default settings restored.': ['Se han restaurado los ajustes predeterminados.','Paramètres par défaut restaurés.','Standardeinstellungen wiederhergestellt.','Predefinições restauradas.','Impostazioni predefinite ripristinate.','Przywrócono ustawienia domyślne.','Стандартні налаштування відновлено.','Varsayılan ayarlar geri yüklendi.','Standaardinstellingen hersteld.'],
  'Delete the cache of automatically found lyrics? Manually imported LRC files will remain.': ['¿Eliminar la caché de letras encontradas automáticamente? Los archivos LRC importados manualmente se conservarán.','Supprimer le cache des paroles trouvées automatiquement ? Les fichiers LRC importés manuellement seront conservés.','Den Cache automatisch gefundener Songtexte löschen? Manuell importierte LRC-Dateien bleiben erhalten.','Eliminar a cache das letras encontradas automaticamente? Os ficheiros LRC importados manualmente serão mantidos.','Eliminare la cache dei testi trovati automaticamente? I file LRC importati manualmente saranno conservati.','Usunąć pamięć podręczną automatycznie znalezionych tekstów? Ręcznie zaimportowane pliki LRC pozostaną.','Видалити кеш автоматично знайдених текстів? LRC-файли, імпортовані вручну, залишаться.','Otomatik bulunan şarkı sözlerinin önbelleği silinsin mi? Elle içe aktarılan LRC dosyaları korunur.','De cache met automatisch gevonden songteksten verwijderen? Handmatig geïmporteerde LRC-bestanden blijven behouden.'],
  'Could not clear the lyrics cache.': ['No se pudo borrar la caché de letras.','Impossible d’effacer le cache des paroles.','Der Songtext-Cache konnte nicht geleert werden.','Não foi possível limpar a cache das letras.','Impossibile svuotare la cache dei testi.','Nie udało się wyczyścić pamięci tekstów.','Не вдалося очистити кеш текстів.','Şarkı sözü önbelleği temizlenemedi.','De songtekstcache kon niet worden gewist.'],
  'Choose how playback starts and moves between tracks.': ['Configura cómo comienza la reproducción y cómo pasa de una canción a otra.','Choisissez comment la lecture démarre et passe d’un titre à l’autre.','Lege fest, wie die Wiedergabe startet und zwischen Titeln wechselt.','Escolha como a reprodução começa e avança entre faixas.','Scegli come avviare la riproduzione e passare da un brano all’altro.','Wybierz sposób rozpoczynania odtwarzania i przechodzenia między utworami.','Вибери, як починається відтворення та як плеєр переходить між треками.','Çalmanın nasıl başlayacağını ve parçalar arasında nasıl geçiş yapılacağını seç.','Kies hoe het afspelen start en tussen nummers wisselt.'],
  'Resume the last selected track when MusPlay starts.': ['Reanuda la última canción seleccionada al iniciar MusPlay.','Reprend le dernier titre sélectionné au démarrage de MusPlay.','Setzt beim Start von MusPlay den zuletzt ausgewählten Titel fort.','Retoma a última faixa selecionada quando o MusPlay é iniciado.','Riprende l’ultimo brano selezionato all’avvio di MusPlay.','Wznawia ostatni wybrany utwór po uruchomieniu MusPlay.','Відновлює останній вибраний трек після запуску MusPlay.','MusPlay başlatıldığında son seçilen parçayı sürdürür.','Hervat het laatst geselecteerde nummer wanneer MusPlay start.'],
  'The next time you open MusPlay, the track resumes from where you stopped.': ['La próxima vez que abras MusPlay, la canción continuará desde donde la dejaste.','Au prochain démarrage de MusPlay, le titre reprendra à l’endroit où vous vous êtes arrêté.','Beim nächsten Öffnen von MusPlay wird der Titel an der letzten Position fortgesetzt.','Na próxima vez que abrir o MusPlay, a faixa continuará de onde parou.','La prossima volta che aprirai MusPlay, il brano riprenderà dal punto in cui ti eri fermato.','Przy następnym uruchomieniu MusPlay utwór będzie kontynuowany od miejsca zatrzymania.','Під час наступного запуску MusPlay трек продовжиться з місця, де ти зупинився.','MusPlay’i bir sonraki açışında parça kaldığın yerden devam eder.','De volgende keer dat je MusPlay opent, gaat het nummer verder vanaf het punt waar je stopte.'],
  'Move to the next queued track when the current song ends.': ['Pasa a la siguiente canción de la cola cuando termine la actual.','Passe au titre suivant de la file lorsque le morceau actuel est terminé.','Wechselt zum nächsten Titel in der Warteschlange, sobald das aktuelle Lied endet.','Avança para a faixa seguinte da fila quando a música atual terminar.','Passa al brano successivo in coda quando termina quello corrente.','Po zakończeniu bieżącego utworu przechodzi do następnego w kolejce.','Після завершення поточної композиції переходить до наступного треку в черзі.','Geçerli şarkı bittiğinde sıradaki parçaya geçer.','Gaat naar het volgende nummer in de wachtrij wanneer het huidige nummer eindigt.'],
  'Fade audio out and back in instead of abrupt track changes.': ['Suaviza el final y el inicio del audio en lugar de cambiar de canción bruscamente.','Fait diminuer puis remonter progressivement le son au lieu de changer brutalement de titre.','Blendet den Ton aus und wieder ein, statt Titel abrupt zu wechseln.','Diminui e aumenta o som gradualmente em vez de mudar de faixa de forma brusca.','Dissolve e ripristina gradualmente l’audio invece di cambiare brano bruscamente.','Stopniowo wycisza i przywraca dźwięk zamiast gwałtownie zmieniać utwory.','Плавно затихає та знову нарощує звук замість різкого перемикання треків.','Parçalar aniden değişmek yerine ses kademeli olarak kısılır ve açılır.','Laat het geluid geleidelijk weg- en terugvallen in plaats van abrupt van nummer te wisselen.'],
  'When you switch tracks manually, the current audio fades out and the next track fades in.': ['Al cambiar de canción manualmente, el sonido actual se desvanece y el siguiente aumenta gradualmente.','Lorsque vous changez de titre manuellement, le son actuel diminue progressivement et le suivant augmente.','Beim manuellen Titelwechsel wird der aktuelle Ton ausgeblendet und der nächste eingeblendet.','Ao mudar de faixa manualmente, o áudio atual diminui gradualmente e a faixa seguinte aumenta.','Quando cambi brano manualmente, l’audio corrente sfuma e il successivo entra gradualmente.','Podczas ręcznej zmiany utworu bieżący dźwięk stopniowo zanika, a następny narasta.','Під час ручного перемикання поточний звук плавно затихає, а наступний поступово стає гучнішим.','Parçayı elle değiştirdiğinde geçerli ses kısılır ve sonraki parça yavaşça açılır.','Wanneer je handmatig van nummer wisselt, vervaagt het huidige geluid en komt het volgende geleidelijk op.'],
  'Higher values create a slower fade.': ['Un valor más alto produce una transición más lenta.','Une valeur plus élevée produit une transition plus lente.','Höhere Werte sorgen für einen langsameren Übergang.','Valores mais altos criam uma transição mais lenta.','Valori più alti producono una dissolvenza più lenta.','Wyższe wartości powodują wolniejsze przejście.','Що вище значення, то повільніший перехід.','Daha yüksek değerler daha yavaş bir geçiş sağlar.','Hogere waarden zorgen voor een langzamere overgang.'],
  'Used for selected items and interactive details.': ['Se utiliza para resaltar elementos y detalles interactivos.','Utilisée pour les éléments sélectionnés et les détails interactifs.','Wird für ausgewählte Elemente und interaktive Details verwendet.','Utilizada em elementos selecionados e detalhes interativos.','Usato per gli elementi selezionati e i dettagli interattivi.','Używany dla zaznaczonych elementów i interaktywnych detali.','Використовується для вибраних елементів та інтерактивних деталей.','Seçili öğeler ve etkileşimli ayrıntılar için kullanılır.','Wordt gebruikt voor geselecteerde items en interactieve details.'],
  'Makes MusPlay interface elements larger or smaller.': ['Aumenta o reduce el tamaño de los elementos de la interfaz de MusPlay.','Agrandit ou réduit les éléments de l’interface de MusPlay.','Vergrößert oder verkleinert die Elemente der MusPlay-Oberfläche.','Aumenta ou diminui os elementos da interface do MusPlay.','Aumenta o riduce gli elementi dell’interfaccia di MusPlay.','Powiększa lub zmniejsza elementy interfejsu MusPlay.','Збільшує або зменшує елементи інтерфейсу MusPlay.','MusPlay arayüz öğelerini büyütür veya küçültür.','Maakt onderdelen van de MusPlay-interface groter of kleiner.'],
  'Reduces track-row height and makes lists more compact.': ['Reduce la altura de las filas de canciones y compacta las listas.','Réduit la hauteur des lignes de titres et rend les listes plus compactes.','Verringert die Höhe der Titelzeilen und macht Listen kompakter.','Reduz a altura das linhas das faixas e torna as listas mais compactas.','Riduce l’altezza delle righe dei brani e rende gli elenchi più compatti.','Zmniejsza wysokość wierszy utworów i zagęszcza listy.','Зменшує висоту рядків треків і робить списки компактнішими.','Parça satırlarının yüksekliğini azaltır ve listeleri daha sıkı hâle getirir.','Verkleint de hoogte van nummerregels en maakt lijsten compacter.'],
  'Shows Now Playing and the queue on the right.': ['Muestra «Reproduciendo ahora» y la cola a la derecha.','Affiche « En cours de lecture » et la file à droite.','Zeigt „Aktuelle Wiedergabe“ und Warteschlange rechts an.','Mostra «A reproduzir» e a fila à direita.','Mostra «In riproduzione» e la coda a destra.','Wyświetla panel „Teraz odtwarzane” i kolejkę po prawej stronie.','Показує блок «Зараз грає» та чергу праворуч.','Şimdi Çalıyor bölümünü ve sırayı sağda gösterir.','Toont Nu aan het afspelen en de wachtrij aan de rechterkant.'],
  'Keep entries for moved or temporarily unavailable audio files.': ['Mantiene en la lista los archivos de audio movidos o temporalmente no disponibles.','Conserve les entrées des fichiers audio déplacés ou temporairement indisponibles.','Behält Einträge für verschobene oder vorübergehend nicht verfügbare Audiodateien bei.','Mantém entradas de ficheiros de áudio movidos ou temporariamente indisponíveis.','Mantiene nell’elenco le voci dei file audio spostati o temporaneamente non disponibili.','Zachowuje wpisy przeniesionych lub tymczasowo niedostępnych plików audio.','Залишає у списку записи про переміщені або тимчасово недоступні аудіофайли.','Taşınan veya geçici olarak kullanılamayan ses dosyalarının kayıtlarını listede tutar.','Behoudt vermeldingen van verplaatste of tijdelijk niet-beschikbare audiobestanden.'],
  'Smooth panel entrances, section changes and button interactions.': ['Suaviza la aparición de paneles, los cambios de sección y las animaciones de los botones.','Fluidifie l’apparition des panneaux, les changements de section et les animations des boutons.','Ermöglicht sanfte Einblendungen von Bereichen, Abschnittswechsel und Schaltflächenanimationen.','Suaviza a entrada dos painéis, as mudanças de secção e as animações dos botões.','Rende più fluide l’apertura dei pannelli, i cambi di sezione e le animazioni dei pulsanti.','Wygładza pojawianie się paneli, przełączanie sekcji i animacje przycisków.','Згладжує появу панелей, перемикання розділів та анімацію кнопок.','Panel açılışlarını, bölüm geçişlerini ve düğme animasyonlarını yumuşatır.','Maakt het verschijnen van panelen, sectiewisselingen en knopanimaties vloeiender.'],
  'Reduces movement and shortens animations even when animations are enabled.': ['Reduce el movimiento y acorta las animaciones aunque estén activadas.','Réduit les déplacements et raccourcit les animations même lorsqu’elles sont activées.','Verringert Bewegungen und verkürzt Animationen, auch wenn sie aktiviert sind.','Reduz o movimento e encurta as animações mesmo quando estão ativadas.','Riduce i movimenti e accorcia le animazioni anche quando sono attive.','Ogranicza ruch i skraca animacje, nawet gdy są włączone.','Зменшує переміщення та скорочує анімації, навіть якщо їх увімкнено.','Animasyonlar açık olsa bile hareketi azaltır ve animasyonları kısaltır.','Vermindert beweging en verkort animaties, zelfs wanneer animaties zijn ingeschakeld.'],
  'Choose when MusPlay looks for new files in your music folders.': ['Elige cuándo MusPlay busca archivos nuevos en tus carpetas de música.','Choisissez quand MusPlay recherche de nouveaux fichiers dans vos dossiers musicaux.','Lege fest, wann MusPlay in deinen Musikordnern nach neuen Dateien sucht.','Escolha quando o MusPlay procura novos ficheiros nas pastas de música.','Scegli quando MusPlay cerca nuovi file nelle cartelle musicali.','Wybierz, kiedy MusPlay ma szukać nowych plików w folderach muzycznych.','Вибери, коли MusPlay шукатиме нові файли в музичних папках.','MusPlay’in müzik klasörlerinde ne zaman yeni dosya arayacağını seç.','Kies wanneer MusPlay naar nieuwe bestanden in je muziekmappen zoekt.'],
  'New tracks from your saved folders are added automatically.': ['Las canciones nuevas de las carpetas guardadas se añaden automáticamente.','Les nouveaux titres des dossiers enregistrés sont ajoutés automatiquement.','Neue Titel aus gespeicherten Ordnern werden automatisch hinzugefügt.','As novas faixas das pastas guardadas são adicionadas automaticamente.','I nuovi brani delle cartelle salvate vengono aggiunti automaticamente.','Nowe utwory z zapisanych folderów są dodawane automatycznie.','Нові композиції зі збережених папок додаватимуться автоматично.','Kaydedilmiş klasörlerdeki yeni parçalar otomatik olarak eklenir.','Nieuwe nummers uit je opgeslagen mappen worden automatisch toegevoegd.'],
  'Automatically rescan folders while MusPlay is running.': ['Vuelve a analizar las carpetas automáticamente mientras MusPlay está abierto.','Analyse automatiquement les dossiers pendant que MusPlay est ouvert.','Durchsucht Ordner automatisch erneut, während MusPlay geöffnet ist.','Volta a analisar as pastas automaticamente enquanto o MusPlay está aberto.','Esegue automaticamente una nuova scansione delle cartelle mentre MusPlay è aperto.','Automatycznie skanuje foldery ponownie, gdy MusPlay jest uruchomiony.','Автоматично перевіряє папки, поки MusPlay відкритий.','MusPlay açıkken klasörleri otomatik olarak yeniden tarar.','Scant mappen automatisch opnieuw zolang MusPlay actief is.'],
  'Manages cached artwork only; music files and tags are not deleted.': ['Gestiona únicamente las carátulas en caché; no se eliminan archivos de música ni etiquetas.','Gère uniquement les pochettes mises en cache ; les fichiers musicaux et leurs tags ne sont pas supprimés.','Verwaltet nur zwischengespeicherte Cover; Musikdateien und Tags werden nicht gelöscht.','Gere apenas as capas em cache; os ficheiros de música e as etiquetas não são eliminados.','Gestisce solo le copertine nella cache; i file musicali e i tag non vengono eliminati.','Zarządza wyłącznie pamięcią okładek; pliki muzyczne i tagi nie są usuwane.','Керує лише кешем обкладинок; музичні файли та теги не видаляються.','Yalnızca önbelleğe alınmış kapakları yönetir; müzik dosyaları ve etiketler silinmez.','Beheert alleen opgeslagen albumhoezen; muziekbestanden en tags worden niet verwijderd.'],
  'Removes cached cover images. MusPlay can read embedded artwork from local audio files again.': ['Elimina las portadas guardadas en caché. MusPlay podrá volver a leer las imágenes incrustadas en los archivos locales.','Supprime les pochettes mises en cache. MusPlay pourra relire les images intégrées aux fichiers audio locaux.','Entfernt zwischengespeicherte Cover. MusPlay kann eingebettete Coverbilder erneut aus lokalen Audiodateien lesen.','Remove as capas em cache. O MusPlay poderá voltar a ler as imagens incorporadas nos ficheiros de áudio locais.','Rimuove le copertine salvate nella cache. MusPlay potrà leggerle di nuovo dai file audio locali.','Usuwa zapisane okładki. MusPlay będzie mógł ponownie odczytać grafiki osadzone w lokalnych plikach audio.','Видаляє збережені обкладинки. MusPlay зможе знову прочитати вбудовані зображення з локальних аудіофайлів.','Önbelleğe alınmış kapak görsellerini kaldırır. MusPlay yerel ses dosyalarındaki gömülü kapakları yeniden okuyabilir.','Verwijdert opgeslagen albumhoezen. MusPlay kan ingesloten afbeeldingen opnieuw uit lokale audiobestanden lezen.'],
  'Clear cached artwork? It can be read again from local files.': ['¿Borrar las portadas guardadas en caché? Se pueden volver a leer desde los archivos locales.','Effacer les pochettes en cache ? Elles pourront être relues depuis les fichiers locaux.','Zwischengespeicherte Cover löschen? Sie können erneut aus lokalen Dateien gelesen werden.','Limpar as capas em cache? Podem voltar a ser lidas a partir dos ficheiros locais.','Cancellare le copertine nella cache? Potranno essere lette di nuovo dai file locali.','Wyczyścić zapisane okładki? Można je ponownie odczytać z plików lokalnych.','Очистити кеш обкладинок? Їх можна буде повторно прочитати з локальних файлів.','Önbelleğe alınmış kapaklar temizlensin mi? Yerel dosyalardan yeniden okunabilirler.','Opgeslagen albumhoezen wissen? Ze kunnen opnieuw uit lokale bestanden worden gelezen.'],
  'Artwork cache cleared.': ['Caché de portadas borrada.','Cache des pochettes effacé.','Cover-Cache geleert.','Cache das capas limpa.','Cache delle copertine svuotata.','Pamięć okładek wyczyszczona.','Кеш обкладинок очищено.','Kapak önbelleği temizlendi.','Albumhoescache gewist.'],
  'Choose when MusPlay searches for synchronized lyrics.': ['Elige cuándo MusPlay busca letras sincronizadas.','Choisissez quand MusPlay recherche des paroles synchronisées.','Lege fest, wann MusPlay nach synchronisierten Songtexten sucht.','Escolha quando o MusPlay procura letras sincronizadas.','Scegli quando MusPlay cerca testi sincronizzati.','Wybierz, kiedy MusPlay ma szukać zsynchronizowanych tekstów.','Вибери, коли MusPlay шукатиме синхронізований текст.','MusPlay’in senkronize şarkı sözlerini ne zaman arayacağını seç.','Kies wanneer MusPlay naar gesynchroniseerde songteksten zoekt.'],
  'Search runs in the background and uses the local cache when lyrics have already been saved.': ['La búsqueda se realiza en segundo plano y utiliza la caché local si la letra ya está guardada.','La recherche s’effectue en arrière-plan et utilise le cache local si les paroles ont déjà été enregistrées.','Die Suche läuft im Hintergrund und verwendet den lokalen Cache, wenn Songtexte bereits gespeichert sind.','A pesquisa decorre em segundo plano e utiliza a cache local se as letras já tiverem sido guardadas.','La ricerca viene eseguita in background e usa la cache locale se il testo è già stato salvato.','Wyszukiwanie odbywa się w tle i korzysta z pamięci lokalnej, jeśli tekst został już zapisany.','Пошук виконується у фоні та використовує локальний кеш, якщо текст уже збережено.','Arama arka planda yapılır ve sözler önceden kaydedilmişse yerel önbelleği kullanır.','Zoeken gebeurt op de achtergrond en gebruikt de lokale cache als songteksten al zijn opgeslagen.'],
  'The lyrics screen opens automatically whenever the track changes.': ['La pantalla de letras se abre automáticamente cada vez que cambia la canción.','L’écran des paroles s’ouvre automatiquement à chaque changement de titre.','Die Songtextansicht wird bei jedem Titelwechsel automatisch geöffnet.','O ecrã das letras abre automaticamente sempre que a faixa muda.','La schermata dei testi si apre automaticamente a ogni cambio di brano.','Ekran tekstu otwiera się automatycznie po każdej zmianie utworu.','Екран тексту автоматично відкривається під час кожної зміни треку.','Parça her değiştiğinde şarkı sözü ekranı otomatik açılır.','Het songtekstscherm wordt automatisch geopend wanneer het nummer verandert.'],
  'Changes the line size in the lyrics view.': ['Cambia el tamaño de las líneas en la vista de letras.','Modifie la taille des lignes dans l’affichage des paroles.','Ändert die Zeilengröße in der Songtextansicht.','Altera o tamanho das linhas na vista das letras.','Modifica la dimensione delle righe nella visualizzazione dei testi.','Zmienia rozmiar wierszy w widoku tekstu.','Змінює розмір рядків у режимі перегляду тексту.','Şarkı sözü görünümündeki satır boyutunu değiştirir.','Wijzigt de regelgrootte in de songtekstweergave.'],
  'Choose how quickly the current line is brought into view.': ['Elige la velocidad con la que se desplaza hasta la línea actual.','Choisissez la vitesse de défilement vers la ligne actuelle.','Lege fest, wie schnell zur aktuellen Zeile gescrollt wird.','Escolha a velocidade de deslocamento até à linha atual.','Scegli la velocità con cui viene portata in vista la riga corrente.','Wybierz szybkość przewijania do bieżącego wiersza.','Вибери швидкість прокручування до поточного рядка.','Geçerli satıra kaydırma hızını seç.','Kies hoe snel naar de huidige regel wordt gescrold.'],
  'Successfully found lyrics are stored on this device and remain available offline.': ['Las letras encontradas correctamente se guardan en este dispositivo y estarán disponibles sin conexión.','Les paroles trouvées sont enregistrées sur cet appareil et restent disponibles hors ligne.','Erfolgreich gefundene Songtexte werden auf diesem Gerät gespeichert und sind offline verfügbar.','As letras encontradas são guardadas neste dispositivo e ficam disponíveis offline.','I testi trovati vengono salvati su questo dispositivo e restano disponibili offline.','Pomyślnie znalezione teksty są zapisywane na tym urządzeniu i dostępne offline.','Успішно знайдені тексти зберігаються на пристрої та доступні офлайн.','Bulunan şarkı sözleri bu cihaza kaydedilir ve çevrimdışı kullanılabilir.','Gevonden songteksten worden op dit apparaat opgeslagen en blijven offline beschikbaar.'],
  'Removes automatically fetched lyrics from the local cache. Manually imported LRC files are kept.': ['Elimina de la caché local las letras obtenidas automáticamente. Los archivos LRC importados manualmente se conservan.','Supprime du cache local les paroles récupérées automatiquement. Les fichiers LRC importés manuellement sont conservés.','Entfernt automatisch abgerufene Songtexte aus dem lokalen Cache. Manuell importierte LRC-Dateien bleiben erhalten.','Remove da cache local as letras obtidas automaticamente. Os ficheiros LRC importados manualmente são mantidos.','Rimuove dalla cache locale i testi scaricati automaticamente. I file LRC importati manualmente vengono conservati.','Usuwa z lokalnej pamięci teksty pobrane automatycznie. Ręcznie zaimportowane pliki LRC pozostają.','Видаляє з локального кешу автоматично отримані тексти. Вручну імпортовані LRC-файли залишаються.','Otomatik alınan sözleri yerel önbellekten kaldırır. Elle içe aktarılan LRC dosyaları korunur.','Verwijdert automatisch opgehaalde songteksten uit de lokale cache. Handmatig geïmporteerde LRC-bestanden blijven behouden.'],
  'Launch MusPlay when you sign in to Windows.': ['Inicia MusPlay al iniciar sesión en Windows.','Lance MusPlay lorsque vous ouvrez une session Windows.','Startet MusPlay, wenn du dich bei Windows anmeldest.','Inicia o MusPlay quando iniciar sessão no Windows.','Avvia MusPlay quando accedi a Windows.','Uruchamia MusPlay po zalogowaniu do systemu Windows.','Запускає MusPlay під час входу до Windows.','Windows’ta oturum açtığında MusPlay’i başlatır.','Start MusPlay wanneer je je aanmeldt bij Windows.'],
  'Shows a Windows notification with the title of the new track.': ['Muestra una notificación de Windows con el título de la nueva canción.','Affiche une notification Windows avec le titre du nouveau morceau.','Zeigt eine Windows-Benachrichtigung mit dem Titel des neuen Titels an.','Mostra uma notificação do Windows com o título da nova faixa.','Mostra una notifica di Windows con il titolo del nuovo brano.','Wyświetla powiadomienie systemu Windows z tytułem nowego utworu.','Показує системне сповіщення Windows із назвою нової композиції.','Yeni parçanın adını içeren bir Windows bildirimi gösterir.','Toont een Windows-melding met de titel van het nieuwe nummer.'],
  'Shortcuts work while the MusPlay window is focused. Press Esc to cancel recording.': ['Los atajos funcionan mientras la ventana de MusPlay está activa. Pulsa Esc para cancelar la grabación.','Les raccourcis fonctionnent lorsque la fenêtre MusPlay est active. Appuyez sur Échap pour annuler l’enregistrement.','Tastenkombinationen funktionieren, solange das MusPlay-Fenster aktiv ist. Mit Esc wird die Aufnahme abgebrochen.','Os atalhos funcionam enquanto a janela do MusPlay estiver ativa. Prima Esc para cancelar a gravação.','Le scorciatoie funzionano quando la finestra di MusPlay è attiva. Premi Esc per annullare la registrazione.','Skróty działają, gdy okno MusPlay jest aktywne. Naciśnij Esc, aby anulować rejestrowanie.','Комбінації працюють, поки вікно MusPlay активне. Натисни Esc, щоб скасувати запис.','MusPlay penceresi etkinken kısayollar çalışır. Kaydı iptal etmek için Esc tuşuna bas.','Sneltoetsen werken zolang het MusPlay-venster actief is. Druk op Esc om de opname te annuleren.'],
  'MusPlay can open audio files from File Explorer. Choose the default app in Windows Settings.': ['MusPlay puede abrir archivos de audio desde el Explorador de archivos. Elige la aplicación predeterminada en la configuración de Windows.','MusPlay peut ouvrir des fichiers audio depuis l’Explorateur de fichiers. Choisissez l’application par défaut dans les paramètres Windows.','MusPlay kann Audiodateien aus dem Datei-Explorer öffnen. Wähle die Standard-App in den Windows-Einstellungen aus.','O MusPlay pode abrir ficheiros de áudio a partir do Explorador de Ficheiros. Escolha a aplicação predefinida nas Definições do Windows.','MusPlay può aprire file audio da Esplora file. Scegli l’app predefinita nelle Impostazioni di Windows.','MusPlay może otwierać pliki audio z Eksploratora plików. Wybierz domyślną aplikację w Ustawieniach systemu Windows.','MusPlay підтримує відкриття аудіофайлів із Провідника. Вибери програму за замовчуванням у налаштуваннях Windows.','MusPlay, Dosya Gezgini’nden ses dosyalarını açabilir. Varsayılan uygulamayı Windows Ayarları’ndan seç.','MusPlay kan audiobestanden openen vanuit Verkenner. Kies de standaard-app in Windows-instellingen.'],
  'Backs up language, theme, playback, appearance, folders and equalizer settings. Music files are not copied.': ['Guarda el idioma, el tema, la reproducción, la apariencia, las carpetas y el ecualizador. No se copian los archivos de música.','Sauvegarde la langue, le thème, la lecture, l’apparence, les dossiers et l’égaliseur. Les fichiers musicaux ne sont pas copiés.','Sichert Sprache, Design, Wiedergabe, Darstellung, Ordner und Equalizer-Einstellungen. Musikdateien werden nicht kopiert.','Faz cópia de segurança do idioma, tema, reprodução, aparência, pastas e equalizador. Os ficheiros de música não são copiados.','Esegue il backup di lingua, tema, riproduzione, aspetto, cartelle ed equalizzatore. I file musicali non vengono copiati.','Tworzy kopię języka, motywu, odtwarzania, wyglądu, folderów i korektora. Pliki muzyczne nie są kopiowane.','Зберігає мову, тему, параметри відтворення, вигляд, папки та еквалайзер. Музичні файли не копіюються.','Dil, tema, oynatma, görünüm, klasörler ve ekolayzır ayarlarını yedekler. Müzik dosyaları kopyalanmaz.','Maakt een back-up van taal, thema, afspelen, vormgeving, mappen en equalizerinstellingen. Muziekbestanden worden niet gekopieerd.'],
  'Restores defaults. Your library, playlists and files remain untouched.': ['Restaura los valores predeterminados. La biblioteca, las listas y los archivos no se modificarán.','Rétablit les valeurs par défaut. Votre médiathèque, vos playlists et vos fichiers restent intacts.','Stellt die Standardwerte wieder her. Mediathek, Playlists und Dateien bleiben unverändert.','Repõe os valores predefinidos. A biblioteca, as listas e os ficheiros permanecem intactos.','Ripristina i valori predefiniti. La libreria, le playlist e i file rimangono invariati.','Przywraca wartości domyślne. Biblioteka, playlisty i pliki pozostają bez zmian.','Повертає стандартні значення. Медіатека, плейлисти та файли залишаться без змін.','Varsayılan değerleri geri yükler. Kitaplığın, çalma listelerin ve dosyaların etkilenmez.','Herstelt de standaardwaarden. Je bibliotheek, afspeellijsten en bestanden blijven onaangeroerd.'],
  'Source code, releases and issue tracking.': ['Código fuente, versiones e informes de errores.','Code source, versions et suivi des problèmes.','Quellcode, Veröffentlichungen und Fehlerberichte.','Código-fonte, versões e acompanhamento de problemas.','Codice sorgente, versioni e segnalazione dei problemi.','Kod źródłowy, wydania i zgłaszanie błędów.','Вихідний код, релізи та повідомлення про помилки.','Kaynak kodu, sürümler ve hata takibi.','Broncode, releases en bugmeldingen.'],
  'News, announcements and MusPlay updates.': ['Noticias, anuncios y novedades de MusPlay.','Actualités, annonces et nouveautés de MusPlay.','Neuigkeiten, Ankündigungen und Updates zu MusPlay.','Notícias, anúncios e novidades do MusPlay.','Notizie, annunci e aggiornamenti di MusPlay.','Wiadomości, ogłoszenia i rozwój MusPlay.','Новини, оголошення та розвиток MusPlay.','MusPlay haberleri, duyuruları ve güncellemeleri.','Nieuws, aankondigingen en updates over MusPlay.'],
  'Third-party library and license information is available in the project files.': ['La información sobre bibliotecas y licencias de terceros está disponible en los archivos del proyecto.','Les informations sur les bibliothèques et licences tierces sont disponibles dans les fichiers du projet.','Informationen zu Bibliotheken und Lizenzen von Drittanbietern findest du in den Projektdateien.','As informações sobre bibliotecas e licenças de terceiros estão disponíveis nos ficheiros do projeto.','Le informazioni sulle librerie e sulle licenze di terze parti sono disponibili nei file del progetto.','Informacje o bibliotekach zewnętrznych i licencjach są dostępne w plikach projektu.','Відомості про сторонні бібліотеки та ліцензії доступні у файлах проєкту.','Üçüncü taraf kitaplıklar ve lisanslar hakkındaki bilgiler proje dosyalarında bulunur.','Informatie over bibliotheken en licenties van derden staat in de projectbestanden.']
};

const extendedLanguages = ['es','fr','de','pt','it','pl','uk','tr','nl'];
for (const [english, translations] of Object.entries(extended)) {
  extendedLanguages.forEach((language, index) => {
    labels[language][english] = translations[index];
  });
}
